D[69175]={"^When you cast Heal, Greater Heal, Flash Heal or Penance on an ally with Weakened Soul, they receive |cFFFFFFFFArmor of Faith|r, which heals them and up to 4 nearby allies for (.-)%% of the heal that granted it after its duration is over or when they take damage%.%s*$","Quando você lança Curar, Grande Curar, Cura Célere ou Penitência sobre um aliado com Alma Enfraquecida, receberão |cFFFFFFFFArmadura da Fé|r, o qual lhes cura a eles e até 4 aliados próximos pelo {{1}}% do sanatório que os concedeu ao finalizar sua duração ou quando recebem dano."}
D[69230]={"^A word of gory darkness that causes your target to bleed for (.-) Shadow damage, increased by 8%% per bleed you have applied to the target%. Lasts (.-)%.%s*$","Uma palavra sombria e sanguinária que faz com que seu alvo sofra hemorragia causando {{1}} de dano de Sombra, aumentado em 8% para cada hemorragia aplicada o alvo. Dura {{2}}."}
D[69231]={"^A word of gory darkness that causes your target to bleed for (.-) Shadow damage, increased by 8%% per bleed you have applied to the target%. Lasts (.-)%.\n\nDamage per bleed increases to a maximum of 40%% and is determined by active bleeds when cast%.%s*$","Uma palavra de escuridão sangrenta faz o alvo sangrar, causando {{1}} de dano de Sombra, aumentado em 8% para cada sangramento seu ativo no alvo. Dura {{2}}.\n\nO bônus por sangramento chega a no máximo 40% e é determinado pelos sangramentos ativos no momento da conjuração."}
D[69471]={"^The White Rider of Conquest demands a challenger!\n\nInflicts the riders Mark damage to all enemies regardless of distance until a challenger has been found%.\n\nThe next Condemnation inflicts (.-)%% increased damage%.\n\nOn Heroic and higher difficulties Condemnation stacks double with every cast%.\n\nStacking up to 100 times%.%s*$","O Cavaleiro Branco da Conquista exige um desafiante!\n\nCausa o dano da Marca do Cavaleiro a todos os inimigos, independentemente da distância, até que um desafiante seja encontrado.\n\nA próxima Condenação causa {{1}}% a mais de dano.\n\nNas dificuldades Heroica e superiores, cada lançamento concede o dobro de acúmulos de Condenação.\n\nAcumula até 100 vezes."}
D[70203]={"^\nThe cooldown of your Avenger's Shield is reduced by 40%% but it no longer slows, jumps to additional targets nor is affected by the Shield of the Templar talent%.%s*$","\nA recarga de sua Escudo Vingador é reduzido em 40% mais não desacelera, salta a alvos adicionais nem está afetado pelo talento Escudo Templário."}
D[71759]={"^Your offensive Priest spell casts have a 5%% chance to cast an additional random Priest spell for free%.%s*$","Suas conjurações de feitiços ofensivos de Sacerdócio têm uma 5% chance de lançar um feitiço aleatório de Sacerdócio adicional sem custo."}
D[71760]={"^Your offensive Priest spell casts have a 10%% chance to cast an additional random Priest spell for free%.%s*$","Suas conjurações de feitiços ofensivos de Sacerdócio têm uma 10% chance de lançar um feitiço aleatório de Sacerdócio adicional sem custo."}
D[71761]={"^Your offensive Priest spell casts have a 15%% chance to cast an additional random Priest spell for free%.%s*$","Suas conjurações de feitiços ofensivos de Sacerdócio têm uma 15% chance de lançar um feitiço aleatório de Sacerdócio adicional sem custo."}
D[71762]={"^Your offensive Priest spell casts have a 20%% chance to cast an additional random Priest spell for free%.%s*$","Suas conjurações de feitiços ofensivos de Sacerdócio têm uma 20% chance de lançar um feitiço aleatório de Sacerdócio adicional sem custo."}
D[71909]={"^Reduces the mana cost of your next Blast Wave or Dragon's Breath by (.-)%% and increases their threat%. Lasts for (.-)%.%s*$","Reduz o custo de mana de seu próximo Onda Explosiva ou Sopro do Dragão em {{1}}% e aumenta sua ameaça. Dura {{2}}."}
D[71911]={"^Dealing damage with Flamestrike reduces the cooldown of your Blast Wave and Dragon's Breath by 1 second%. This effect only triggers once per second%.%s*$","Causar dano com Coluna de Chamas reduz em 1 s a recarga de Onda Explosiva e Sopro do Dragão. Este efeito só pode ocorrer uma vez por segundo."}
D[71913]={"^Your Judgements now grant you Templar of Flame%.%s*$","Seu Juízes agora concede a você a bênção de Templário do Fogo."}
D[71914]={"^Your Judgements now grant you |cFFFFFFFFThreat of the Templar|r%.%s*$","Seu Julgamento agora concede a você |cFFFFFFFFAmeaça do Templário|r."}
D[72052]={"^Your direct damaging spells and abilities now have a (.-)%% chance to Smite your target, dealing (.-) additional Holy damage and healing nearby party members for a (.-)%.%s*$","Agora seus feitiços e habilidades de dano direto têm {{1}}% de chance de Flagelar ao alvo, causando {{2}} de dano Sagrado adicional e curando os membros próximos do grupo em {{3}}."}
D[72053]={"^Your direct damaging spells and abilities now have a (.-)%% chance to Smite your target, dealing (.-) additional Holy damage and healing nearby party members for a (.-)%.\n\nThis damage uses Smite modifiers and can only occur once every 4%.5 seconds%. Deals 80%% damage and healing when triggered against enemy players%.%s*$","Agora seus feitiços e habilidades de dano direto têm {{1}}% de chance de Flagelar ao alvo, causando {{2}} de dano Sagrado adicional e curando os membros próximos do grupo em {{3}}.\n\nEste dano use modificadores de Flagelar e Pode ocorrer uma vez a cada 4.5 segundos. Causa 80% de dano e cura quando ativado contra jogadores inimigos."}
D[72054]={"^Your damaging abilities (.-)%% have a chance to Smite your target, dealing additional Holy damage and healing nearby party members for a small amount%. This effect scales with your Smite ability%.%s*$","Suas habilidades de dano têm {{1}}% de chance de usar Punição contra o alvo, causando dano Sagrado adicional e curando os membros próximos do grupo em uma pequena quantidade. Essefeito é ampliado por Punição."}
D[72055]={"^Your damaging abilities (.-)%% have a chance to Smite your target, dealing additional Holy damage and healing nearby party members for a small amount%. This effect scales with your Smite ability%. \n\nEffectiveness reduced by 80%% against players%. This effect cannot occur more than once every 4%.5 seconds%.%s*$","Suas habilidades de dano têm {{1}}% de chance de usar Punição contra o alvo, causando dano Sagrado adicional e curando os membros próximos do grupo em uma pequena quantidade. Essefeito é ampliado por Punição.\n\nA eficácia é reduzida em 80% contra jogadores. Essefeito só pode ocorrer uma vez a cada 4,5 s."}
D[72833]={"^Increases the damage of your next Hammer of the Righteous by (.-)%%%.%s*$","Aumenta o dano de seu próximo Martelo do Direito em {{1}}%."}
D[72834]={"^SE1 Reduces the cooldown of Hammer of the Righteous by (.-)%s*$","RE1 Reduz a recarga do Martelo do Direito em {{1}}."}
D[72899]={"^Your Holy Shock, Flash of Light, Holy Light, Hammer of Wrath and Judgements reduces the cooldown of Tyr's Deliverance by (.-) sec%.%s*$","Seu Acerto Sagrado, Brilho de Luz, Luz Sagrada, Martelada do Pecado e Julgamentos reduzem a recarga dá Entrega de Tyr em {{1}} s."}
D[72945]={"^Launch a powerful swing, dealing (.-)%% weapon damage to up to (.-) enemies in a cone in front of you%.\n\nMax 3 charges, 8 seconds recharge timer%.%s*$","Lança um poderoso golpe, causando dano da arma em {{1}}% até {{2}} inimigos em uma cone à sua frente.\n\nMax 3 cargas, recarga de 8 s."}
