T[10151]={"^All stats increased by (.-)%%%. Stacks (.-) times%.%s*$","Todas as estatísticas aumentadas em {{1}}%. Acumula {{2}} vezes."}
T[10416]={"^Your Raise and Animate spells cost no mana and are instant cast%.%s*$","Seus feitiços de Animar e Animar não consomem mana e são instantâneos."}
T[10423]={"^Allows you to use a Follow Up Ability such as Righteous Lunge, Condemn, Holy Cleave, Vindication, and Vindication%.%s*$","Permite que use uma Habilidade de Seguimento como Lançamento Desafio, Condenação, Corte Sagrado, Vindicação e Vindicação."}
T[10911]={"^(.-) damage is being staggered every second%.%s*$","{{1}} de dano se está absorvendo a cada segundo."}
T[12605]={"^Threat of your next Blast Wave or Dragon's Breath increased by (.-)%%, and mana cost reduced by (.-)%%%.%s*$","A ameaça de seu próximo Explosão Wave ou Sopro do Dragão aumenta em {{1}}%, e o custo de mana é reduzido em {{2}}%."}
T[13116]={"^Your Holy Fire and Smite casts are 20%% faster and reduce the cooldown of Holy Word: Chastise by 2 seconds%.%s*$","Seus Lançamentos de Fogo Sagrado e Flagelo são 20% mais rápidas e reduzem a recarga de Palavra Sagrada: Castigar em 2 segundos."}
T[14105]={"^Meditating, regenerating (.-)%% maximum health every (.-) sec%. Damage taken reduced by (.-)%%%.\n\nRemoving 1 disease effect with each tick%.%s*$","Meditando, restaurando {{1}}% da vida máxima a cada {{2}} segundos. Dano recebido reduzido em {{3}}%.\n\nRemove 1 efeito de doença cada aplicação."}
T[14377]={"^Your next Righteous Lunge strikes 5 additional nearby enemies%.%s*$","Seu próximo Salto Lícita atingirá a 5 inimigos adicionais próximos."}
T[14428]={"^At 10 stacks, Chastise becomes Divine Fury%.%s*$","A partir de 10 acúmulos, Castigo transforma-se em Força Divina."}
T[14579]={"^Allows you to have up to 2 |cffffffffOaths|r on you at a time%.%s*$","Permite manter até 2 |cffffffffJuramentos|r ativos ao mesmo tempo."}
T[14808]={"^Healing an ally now redirects (.-)%% of their damage taken to you and reduces your damage taken by (.-)%% for (.-), stacking (.-) times%.%s*$","Curar um aliado redireciona para você {{1}}% do dano que ele recebe e reduz em {{2}}% o dano que você recebe durante {{3}}. Acumula até {{4}} vezes."}
T[14861]={"^Causes your next 3 Chakram spells to cause a Damage over Time effect%.%s*$","Causa um efeito de Dano ao longo do tempo com seus próximos 3 feitiço Chakram."}
T[14964]={"^Causes your critical strikes to generate a stack of Zephyr%.%s*$","Faz seus acertos críticos gerem um acúmulo de zéfiro."}
T[14998]={"^Reduces the cast time of Sunflare and Radiant Flame by 0%.5 sec%.%s*$","Reduz o tempo de lançamento de Raio Solar e Chama Radiante em 0,5 s."}
T[15017]={"^Enraged%. Attack Speed increased by (.-)%%, Physical Damage done increased by (.-)%%, Movement Speed increased by (.-)%%%. Lasts for up to 5 Physical Attacks%.%s*$","Enfurecido. Aumenta velocidade de ataque em {{1}}%, o dano Físico causado aumenta em {{2}}%, e a velocidade de movimento aumenta em {{3}}%. Dura até 5 ataques físicos."}
T[15567]={"^The White Rider of Conquest demands a challenger!\n\nInflicts the riders Mark damage to all enemies regardless of distance until a challenger has been found%.\n\nThe damage increases for each stack of Condemnation on the target%.%s*$","O Cavaleiro Branco da Conquista exige um desafiante!\n\nCausa o dano da Marca do Cavaleiro a todos os inimigos, independentemente da distância, até que um desafiante seja encontrado.\n\nO dano aumenta para cada acúmulo de Condenação no alvo."}
T[15568]={"^Inflicts Holy damage to the target, increased for each stack of Condemnation on the target%.%s*$","Causa dano Sagrado ao alvo, aumentado para cada acúmulo de Condenação nele."}
T[15585]={"^O'mroggs Left Head decided to kill someone else%.\nImmune to taunts%.%s*$","A Cabeça Esquerda do'mrogg decidiu matar a outra pessoa.\nImune às provocações."}
T[16021]={"^O'mroggs Left Head decided to kill someone else%.\nImmune to taunts%.%s*$","A Cabeça Esquerda do'mrogg decidiu matar a outra pessoa.\nImune às provocações."}
T[17146]={"^Dealing damage with Flamestrike reduces the cooldown of your Blast Wave and Dragon's Breath by 1 second%. This effect only triggers once per second%.%s*$","Causar dano com Coluna de Chamas reduz em 1 s a recarga de Onda Explosiva e Sopro do Dragão. Este efeito só pode ocorrer uma vez por segundo."}
T[17213]={"^Generic iCD%s*$","Genérico iCD."}
T[17544]={"^SLS for 277977\nTriggers 277979%s*$","Desencadeia 277977\nAtiva 277979"}
T[17545]={"^Increases the damage of your next Hammer of the Righteous by (.-)%%%(s2%% against players%)%.%s*$","Aumenta o dano de seu próximo Martelo do Direito em {{1}}%(s2% contra jogadores)."}
T[17546]={"^SE1 Reduces the cooldown of Hammer of the Righteous by (.-)%s*$","RE1 Reduz a recarga do Martelo do Direito em {{1}}."}
T[17570]={"^Tyr's Deliverance cooldown reduction%s*$","redução da recarga dá Entrega de Tyr."}
T[18730]={"^Heals for 1 for a proc check of Soul Bind to limit it to not bounce targets, which could kill you as its a blessing of sacrifice%.%s*$","Curará por 1, realizando uma verificação de ativação do Benefícios Vínculo Anímico para limitá-lo a que não rebote entre alvos, o qual poderá matar você já que é uma bênção de sacrifício."}
T[18918]={"^Reduces the damage dealt to the Templar by 10%%%.%s*$","Reduz o dano recebido pelo Templário em 10%."}
T[19492]={"^Every 6 seconds in combat, you gain either Divine Absolution or Unholy Absolution%.\n\nDivine Absolution increases your Spirit by (.-)%% and Critical Strike Rating by (.-)%% of your Spirit%.\n\nUnholy Absolution increases your Spell Haste by (.-)%% and your Spell Power by (.-)%% of your Spirit%. \n\nBoth effects can not occur simultaneously%.%s*$","a cada 6 segundos em combate, obtém já seja Absolução Divina ou Absolução Diabrura.\n\nAbsolução Divina aumenta seu Espírito em {{1}}% e seu Pontuação de Acerto crítico em {{2}}% de seu Espírito.\n\nAbsolução Diabrura aumenta sua aceleração com Feitiços em {{3}}% e seu poder mágico em {{4}}% de seu Espírito.\n\nAmbos os efeitos não podem acontecer simultaneamente."}
T[20632]={"^Dealing damage with Flamestrike reduces the cooldown of your Blast Wave and Dragon's Breath by 2 seconds %(1 versus players%)%. This effect only triggers once per second%.%s*$","Causar dano com Acerto de Fogo reduz a recarga de sua Onda de Impacto e Sopro do Dragão em 2 segundos (1 contra jogadores). Este efeito só é ativado uma vez por segundo."}
T[21172]={"^Your Holy Fire and Smite casts are 20%% faster and reduce the cooldown of Holy Word: Chastise by 2 seconds%.%s*$","Seus Lançamentos de Fogo Sagrado e Flagelo são 20% mais rápidas e reduzem a recarga de Palavra Sagrada: Castigar em 2 segundos."}
T[21605]={"^Attack power reduced by (.-)%.%s*$","Poder de ataque reduzido em {{1}}."}
T[21664]={"^Restores (.-) mana per second%.%s*$","Recupera {{1}} de mana por segundo."}
T[22841]={"^Strength and Agility reduced by (.-)%%%.%s*$","Força e agilidade reduzidas {{1}}%."}
T[22900]={"^Dodge chance increased by (.-)%%%.%s*$","chance de esquiva em {{1}}% aumentada em."}
T[23687]={"^Critical Strike Rating and Spirit increased by (.-)%.%s*$","Índice de acerto crítico e Espírito aumentou {{1}} p."}

